package org.hvmhealth.checks

/**
 * What every check id means, in words for an operator at 3am: the tab's popups and Help, and docs/CHECKS.md, come from here.
 * Written from the code in HealthChecker and HealthMonitor. CheckCatalogSpec fails when an id or a standards key is missing from it,
 * or when the file falls behind. It holds no cluster data.
 *
 * "Seen" and "measured" mean in real runs, often few of them. "Built from documentation" means it has not met the real thing yet. Keep that distinction.
 */
class CheckCatalog {
    /** The start of "what" on every check in HealthMonitor.FULL_ONLY, and only on those. */
    static final String FULL_ONLY_NOTE = 'Full check only.'

    /** Worst first, as the tab sorts them. */
    static final List<Map<String, String>> STATUSES = [
            [status: 'FAIL', meaning: 'Wrong now. Raises an error alarm in Morpheus.'],
            [status: 'WARN', meaning: 'Wrong or at risk, but not a failure. Raises a warning alarm in Morpheus.'],
            [status: 'NOT_CHECKED', meaning: 'The check applies, but could not be answered here, usually for want of a tool on the host. It says nothing either way. It raises no alarm, and one already open stays open.'],
            [status: 'NA', meaning: 'The check does not apply here, or is only a note. No alarm.'],
            [status: 'PASS', meaning: 'Fine at the last check. The readiness table shows this as OK.'],
    ]

    static final Map<String, String> PREFIXES = [
            CAP: 'Capacity',
            CLU: 'Cluster membership',
            DLM: 'DLM locking',
            FEN: 'Fencing',
            GFS: 'GFS2',
            HA : 'High availability',
            HB : 'Heartbeats',
            HST: 'Host',
            HW : 'Hardware',
            LAY: 'Layout',
            MIG: 'Migration',
            MOR: 'Morpheus\'s view',
            NET: 'Network',
            PKG: 'Packages',
            PRB: 'The plugin itself',
            STO: 'Storage',
            TIM: 'Time',
            VM : 'VMs',
    ]

    static final List<String> NOTES = [
            'Automatic checks are quick checks, with a full check on a longer interval. Run full check runs one now. A check marked "Full check only" keeps its last answer between full checks.',
            'A key named here is a site standard: the Standards in force section shows its value, and the Site standards plugin setting overrides it. Listing an id in disabledChecks there drops that check.',
            'The HCI Ceph layout skips the DLM, GFS2 and heartbeat checks, and has no Ceph checks.',
            '"Seen" and "measured" mean in real runs, often few of them. "Built from documentation" means the check has not met the real thing yet.',
    ]

    static final Map<String, Map<String, String>> ENTRIES = [
            // ------------------------------------------------------------------ capacity
            'CAP-01': [area: 'Capacity', name: 'VMs fit on the remaining hosts if the largest fails',
                       what: 'Adds up the memory of the running VMs in Morpheus and compares it with the host memory left without the largest host. WARN: they would not fit. Runs only with 2 or more hosts, and a memory size from Morpheus for each.',
                       why: 'Memory is the limit that stops a restart. If they do not fit, automatic failover could not restart every VM, and some tenants would stay down until a host returned.',
                       action: 'Decide whether that risk is acceptable. Clearing it takes fewer running VMs or more host memory. The plugin has no fix for this.'],

            // ------------------------------------------------------------------ membership
            'CLU-01': [area: 'Cluster membership', name: 'Enough hosts for quorum',
                       what: 'Counts the hosts Morpheus has in this cluster against the site standard minHosts. A witness does not count, so this fails under the minimum even with one.',
                       why: 'With fewer hosts, one failure stops every GFS2 datastore.',
                       action: 'Add a host or a witness. Sources disagree on two-host GFS2, so minHosts is a judgement you can override.'],
            'CLU-02': [area: 'Cluster membership', name: 'corosync and dlm running and enabled',
                       what: 'Reads systemctl for corosync and for dlm on each host. PASS: running and enabled at boot. WARN: running, but not enabled. FAIL: not running.',
                       why: 'A host without them is not a working cluster member. One that is running but not enabled does not come back after a reboot.',
                       action: 'WARN: press Fix (service-enable), which only enables them at boot and is safe any time. FAIL: Fix offers rejoin, on a host in maintenance mode with no VMs. It refuses if GFS2 is mounted: that host needs a reboot in a maintenance window instead. After a rejoin, reboot before leaving maintenance mode. No corosync.conf: add the host back through Morpheus. Empty authkey: see CLU-13.'],
            'CLU-03': [area: 'Cluster membership', name: 'Host sees a quorate cluster',
                       what: 'Reads corosync-quorumtool -s on each host where corosync runs. FAIL: this host says it is not quorate.',
                       why: 'A host outside a quorate cluster is not part of a working cluster, and a fence acknowledgement cannot complete there, so a freeze cannot be cleared from it.',
                       action: 'Restore quorum first. CLU-04, CLU-05 and CLU-08 show which member is missing or cut off.'],
            'CLU-04': [area: 'Cluster membership', name: 'Quorum margin: a host can fail without losing quorum',
                       what: 'Compares total votes, expected votes and the quorum from corosync-quorumtool. PASS: every expected vote is present. WARN: a vote is missing, with votes to spare above quorum. FAIL: a vote is missing and no margin is left.',
                       why: 'One more failure at no margin stops every datastore.',
                       action: 'A member is missing. Find out which and why before any host work.'],
            'CLU-05': [area: 'Cluster membership', name: 'corosync nodelist matches the hosts Morpheus has in this cluster',
                       what: 'Compares each host\'s corosync.conf nodelist with Morpheus\'s hosts, by ring address and then by name. FAIL lists what is in corosync only and what is in Morpheus only.',
                       why: 'A node corosync counts but Morpheus no longer manages led to the freeze this plugin was built around. If it goes down or is rebuilt without leaving the cluster, every GFS2 datastore freezes until it is acknowledged as fenced.',
                       action: 'In corosync only: remove it from the cluster properly before touching that node. Morpheus\'s own remove can leave this behind when GFS2 will not unmount, and once the record has gone HVM\'s agent may not acknowledge it either. In Morpheus only: this host\'s corosync.conf does not list it, so compare with CLU-06.'],
            'CLU-06': [area: 'Cluster membership', name: 'corosync.conf identical on every host',
                       what: 'Compares config_version and the node ids and addresses across every host with a corosync.conf. FAIL: they differ.',
                       why: 'Hosts working from different files disagree about who is in the cluster.',
                       action: 'Find the host that differs from the versions shown. The plugin has no fix for this: it never restarts corosync with GFS2 mounted.'],
            'CLU-07': [area: 'Cluster membership', name: 'corosync authkey identical on every host',
                       what: 'Compares a truncated hash of /etc/corosync/authkey across hosts. The key itself never leaves the host.',
                       why: 'Members of one cluster share this key, so a host with another one is not properly part of it.',
                       action: 'Find the host that differs. An empty key shows here too: see CLU-13. The plugin has no fix for this.'],
            'CLU-08': [area: 'Cluster membership', name: 'Corosync links connected',
                       what: 'Reads corosync-cfgtool -s on each host where corosync runs. FAIL lists the peers whose link is not connected.',
                       why: 'Cluster membership runs over these links, so a lost link puts a member at risk.',
                       action: 'Check the cluster network between the two hosts. NET-01, NET-03 and NET-10 look at the same path.'],
            'CLU-09': [area: 'Cluster membership', name: 'corosync consensus timeout at least 1.2 x token',
                       what: 'Compares totem.consensus with totem.token in corosync.conf, where both are set. The ratio is the site standard consensusRatio. FAIL: consensus is too short.',
                       why: 'corosync.conf(5) sets this minimum.',
                       action: 'Correct the values in corosync.conf. The plugin has no fix for this: it never restarts corosync with GFS2 mounted.'],
            'CLU-10': [area: 'Cluster membership', name: 'corosync token timeout matches the standard',
                       what: 'Compares totem.token in corosync.conf with the site standard corosyncToken. WARN: it differs. Pinned on 1.3, to what that layout deploys. Not pinned on 2.0 yet, so it runs there only if you set the key.',
                       why: 'Membership only changes after the token and consensus timeouts, so they set how long a lost host goes unnoticed while GFS2 stalls.',
                       action: 'Find out why it differs from what the layout deploys, or set corosyncToken if this value is what you want.'],
            'CLU-11': [area: 'Cluster membership', name: 'corosync consensus timeout matches the standard',
                       what: 'Compares totem.consensus in corosync.conf with the site standard corosyncConsensus. WARN: it differs. Pinned on 1.3, to what that layout deploys. Not pinned on 2.0 yet, so it runs there only if you set the key.',
                       why: 'Membership only changes after the token and consensus timeouts, so they set how long a lost host goes unnoticed while GFS2 stalls.',
                       action: 'Find out why it differs from what the layout deploys, or set corosyncConsensus if this value is what you want.'],
            'CLU-12': [area: 'Cluster membership', name: 'Quorum device connected and voting',
                       what: 'Where corosync.conf has a quorum device, reads corosync-qdevice-tool and corosync-quorumtool on each host. NA: no device. WARN: lost, with votes to spare. FAIL: lost with no margin, or missing from this host\'s corosync.conf while others have it. NOT CHECKED: nothing reported its state. Built from documentation: not yet run against a real witness.',
                       why: 'Losing it leaves the hosts quorate while they agree, but the tiebreak and the margin it gave are gone.',
                       action: 'Check corosync-qdevice on this host and qnetd on the witness.'],
            'CLU-13': [area: 'Cluster membership', name: 'Corosync authkey has something in it',
                       what: 'Fails when /etc/corosync/authkey on a host is an empty file. There is no row when it is fine.',
                       why: 'Adding this host did not finish. Morpheus can show it as provisioned while corosync cannot start, leaving the others a vote short.',
                       action: 'Delete the host in Morpheus and add it again, which has worked each time. Fix does not offer rejoin on such a host.'],

            // ------------------------------------------------------------------ DLM
            'DLM-01': [area: 'DLM locking', name: 'Lockspaces waiting for a node to be fenced',
                       what: 'A lockspace on this host is stopped, and dlm_tool status shows it waiting for the named node to be fenced. All GFS2 I/O on this host is blocked.',
                       why: 'Every heartbeat and metadata change on GFS2 is frozen until the node is acknowledged as fenced. HVM\'s agent normally does this within about 2 minutes, so a wait that lasts longer will not clear by itself. If it runs on, the agent decides its datastores are dead and stops VMs: seen at about 9 minutes, in the one run that reached it, and they power off the moment I/O returns.',
                       action: 'Use the emergency panel on this tab, which needs the Cluster Health Emergency Actions permission and the node\'s name typed. It runs dlm_tool fence_ack. Only acknowledge once the node is certainly down: acknowledging a node that can still write corrupts the filesystem. It is never automatic. Afterwards, start any VMs the agent powered off.'],
            'DLM-02': [area: 'DLM locking', name: 'HVM agent is acknowledging the failed node',
                       what: 'After 3 minutes of a fence wait, looks in this host\'s journal for the agent\'s dlm_tool fence_ack commands in the last 15 minutes. FAIL: it acknowledged other nodes or nothing, never the failed one. Not judged on a host that ran out of time.',
                       why: 'The freeze will not clear by itself. In a real freeze an older agent acknowledged the other hosts and never the failed node.',
                       action: 'Usually the node has gone from Morpheus while corosync still counts it: see CLU-05. To end the freeze, follow DLM-01.'],
            'DLM-03': [area: 'DLM locking', name: 'DLM lockspaces running',
                       what: 'Reads dlm_tool ls on hosts where dlm runs. It is judged only while the host is not frozen, and frozen is the same test, so as written it reads PASS or does not appear. A stopped lockspace with a fence wait shows as DLM-01.',
                       why: 'While a lockspace is stopped, any access to a GFS2 mount on that host blocks.',
                       action: 'Nothing on PASS. If the Hosts section says FROZEN with no DLM-01, press Raw there and read dlm_tool ls for that host.'],
            'DLM-04': [area: 'DLM locking', name: 'dlm.conf enable_fencing',
                       what: 'Reads enable_fencing in /etc/dlm/dlm.conf on hosts where dlm runs, against the site standard fencingEnabled. FAIL: it differs, or is unset.',
                       why: 'GFS2 must not recover until a failed node is known to be down. With fencing off it would recover while that node may still write, which corrupts the filesystem.',
                       action: 'Make dlm.conf match. Do not turn fencing off to get past a freeze. The plugin has no fix for this.'],
            'DLM-05': [area: 'DLM locking', name: 'Hosts agree on lockspace members',
                       what: 'Compares the members of each lockspace across hosts, from dlm_tool ls. FAIL: hosts list different members.',
                       why: 'Hosts that disagree on who holds a lockspace are not in one settled cluster.',
                       action: 'Run the check again, as this can be a cluster still changing. If it stays, find the host that differs before any host work.'],
            'DLM-06': [area: 'DLM locking', name: 'dlm_controld is not fencing a departed node',
                       what: 'WARN: dlm_controld is still retrying a fence for a node, with every lockspace on this host running. This is not a freeze.',
                       why: 'GFS2 I/O is not blocked. This was seen for minutes after a host left cleanly.',
                       action: 'There is nothing to acknowledge unless a lockspace stops, which would show as DLM-01.'],

            // ------------------------------------------------------------------ fencing
            'FEN-01': [area: 'Fencing', name: 'Host management controller known',
                       what: 'Full check only. Reads the management controller\'s address with ipmitool. WARN: none found, which can also mean the tool is there without its driver. NOT CHECKED: ipmitool is not installed, as on Morpheus-built hosts, so the host may well have one.',
                       why: 'Without one there is no out-of-band way to prove a failed host is powered off.',
                       action: 'Install ipmitool to let the plugin read it. WARN: check the controller is configured.'],

            // ------------------------------------------------------------------ GFS2
            'GFS-01': [area: 'GFS2', name: 'No withdrawn GFS2 filesystems',
                       what: 'Reads withdraw under /sys/fs/gfs2 for each mounted filesystem. FAIL: one has withdrawn.',
                       why: 'A withdrawn filesystem stays unusable on this host until it is unmounted and remounted.',
                       action: 'Move its VMs off in a maintenance window. Check storage paths first, since lost I/O is the usual cause. See GFS-10 for the log.'],
            'GFS-02': [area: 'GFS2', name: 'Every GFS2 datastore mounted on this host',
                       what: 'Compares each host\'s mounted GFS2 lock tables with all those seen on any host. FAIL: this host is missing one.',
                       why: 'A VM on a datastore this host has not mounted cannot run here, so it counts against live migration.',
                       action: 'In maintenance mode: reboot this host before it leaves maintenance mode, which brings GFS2 back. Leaving without that has made the agent force a reboot. Otherwise find out why it is not mounted.'],
            'GFS-03': [area: 'GFS2', name: 'GFS2 lock tables belong to this cluster',
                       what: 'Checks each mounted lock table starts with this cluster\'s name from corosync.conf. FAIL lists those that do not.',
                       why: 'It is a filesystem from another cluster, or an unresignatured snapshot clone. Two clusters mounting one GFS2 filesystem corrupts it.',
                       action: 'Find out where that filesystem came from. The plugin has no fix for this.'],
            'GFS-04': [area: 'GFS2', name: 'GFS2 datastore space',
                       what: 'Reads df on each GFS2 mount when DLM says that is safe. WARN and FAIL at the site standards gfs2WarnPct and gfs2FailPct.',
                       why: 'VM disks on the datastore need room to grow.',
                       action: 'Free space or add capacity. GFS-09 shows whether the largest VM could still move there.'],
            'GFS-05': [area: 'GFS2', name: 'No hung kernel tasks',
                       what: 'Counts "blocked for more than" reports in the kernel log over the last hour. WARN at the site standard hungTasksWarn. Tasks in D state now are shown, and do not change the status.',
                       why: 'Tasks stuck on I/O are how lost storage or a stopped lockspace shows up on a host.',
                       action: 'Check DLM-01 first, then storage latency and paths (STO-06, STO-01).'],
            'GFS-06': [area: 'GFS2', name: 'GFS2 journals cover every host',
                       what: 'Full check only. Counts each filesystem\'s journals with gfs2_edit when DLM says that is safe, against the hosts in the cluster. WARN: too few.',
                       why: 'A host beyond the journal count cannot mount this filesystem.',
                       action: 'Add journals before adding hosts. The plugin has no fix for this.'],
            'GFS-07': [area: 'GFS2', name: 'GFS2 answers promptly',
                       what: 'FAIL: df and heartbeat reads did not finish in 15 s although DLM looks healthy. There is no row when they finish.',
                       why: 'Slow GFS2 with healthy DLM points below it, at the storage, and VM disks wait the same way.',
                       action: 'Look at storage latency and paths next (STO-06, STO-01).'],
            'GFS-08': [area: 'GFS2', name: 'GFS2 metadata responsive',
                       what: 'Times reading a heartbeat file\'s attributes, which takes a cluster lock. WARN over the site standard gfs2StatWarnMs.',
                       why: 'This is how long a VM\'s metadata access would wait.',
                       action: 'Compare with STO-06 on the same host, and with the other hosts.'],
            'GFS-09': [area: 'GFS2', name: 'Room to move the largest VM onto this datastore',
                       what: 'Compares free space with the largest VM\'s disks not already there, at full size. WARN: a VM whose disks are known to be elsewhere would not fit. NOT CHECKED: Morpheus gave no sizes, or did not say where the disks are. NA: every VM is already there. Rests on Morpheus\'s datastore name matching the libvirt pool name, which is not proven.',
                       why: 'A storage migration onto this datastore would not fit at the disks\' full size. A thin disk may need less.',
                       action: 'Free space there before planning that move, or choose another datastore.'],
            'GFS-10': [area: 'GFS2', name: 'No GFS2 consistency errors or withdrawals',
                       what: 'Searches the kernel log over 7 days for GFS2 consistency errors and withdrawals. NOT CHECKED: the log could not be read. With a journal that does not persist across reboots, it loses what a reboot clears.',
                       why: 'A reboot clears the live state, and HVM\'s agent reboots a host soon after a withdrawal, so this log is the evidence that remains.',
                       action: 'Run fsck.gfs2 -n with every host unmounted when you can, and raise it with HPE. It clears 7 days after the event.'],

            // ------------------------------------------------------------------ high availability
            'HA-01': [area: 'High availability', name: 'Morpheus notHighAvailability flag (for information)',
                      what: 'Shows the raw notHighAvailability value from the cluster record. It is a note, never a finding: always NA, never an alarm.',
                      why: 'Its meaning is unknown. HPE does not document it, Morpheus has set it on every cluster seen so far, and flipping it changed nothing visible. It says nothing about this cluster on its own.',
                      action: 'Nothing to do. Do not read it as a verdict on high availability.'],
            'HA-02': [area: 'High availability', name: 'Host in maintenance mode is still a cluster member',
                      what: 'WARN on any host in maintenance mode that corosync and DLM still count. There is no row otherwise.',
                      why: 'Maintenance mode empties a host but does not take it out of the cluster. Powering it off now stalls every GFS2 datastore on the other hosts for about 2 minutes while HVM\'s agent acknowledges it, and freezes them if the agent does not.',
                      action: 'Remove it from the cluster first, with Remove safely in the Hosts section (Can I take it down?). Morpheus\'s own Remove carries on if GFS2 will not unmount, and those checks do not run on it.'],
            'HA-03': [area: 'High availability', name: '"Automatically Power On VMs" is on for this cluster',
                      what: 'Reads the setting from the cluster record, or else from the heartbeat files, as the plugin API has no member for it: with it off the agents stop writing them, so fresh files mean on. WARN: off. NOT CHECKED: neither gave an answer. NA: fewer than 2 hosts. Whether the heartbeat reading holds on 2.0 is not proven.',
                      why: 'With it off, Morpheus will not power on VMs that a lost host took down, so they stay down until someone starts them.',
                      action: 'Edit the cluster and turn it on, unless that is what you want.'],
            'HA-04': [area: 'High availability', name: '"Automatically Power On VMs" on this cluster\'s cloud',
                      what: 'Shows the cloud\'s setting, for information. NA: always, with its value. NOT CHECKED: Morpheus gave no value.',
                      why: 'The cluster\'s setting is the one that decides: with the cloud\'s off and the cluster\'s on, the agent restarted VMs.',
                      action: 'Nothing to do. Look at HA-03.'],
            'HA-05': [area: 'High availability', name: 'A datastore is the heartbeat target',
                      what: 'PASS: Morpheus flags a datastore, or hosts are writing heartbeat files, which is what matters. WARN: neither. NOT CHECKED: Morpheus flags none and GFS2 could not be read, or it listed no datastores. NA on HCI Ceph.',
                      why: 'Without one, Morpheus only finds a lost host at its next cluster sync, about 5 minutes by default according to HPE staff, rather than within seconds.',
                      action: 'Edit a shared datastore and make it the heartbeat target.'],
            'HA-06': [area: 'High availability', name: 'The Morpheus manager runs outside this cluster',
                      what: 'Looks for a VM on this cluster with one of the appliance\'s own addresses. WARN: it found one. No row when the addresses cannot be read. Not yet run on a real cluster with its manager on it.',
                      why: 'A freeze on this cluster would take down the console and every alarm, including this one. That happened in the freeze this plugin was built around.',
                      action: 'Move the manager, or watch these hosts from somewhere else as well.'],

            // ------------------------------------------------------------------ heartbeats
            'HB-01': [area: 'Heartbeats', name: 'Host heartbeat current',
                      what: 'Reads each host\'s heartbeat file on GFS2, from one host where DLM says that is safe. FAIL: older than the site standard heartbeatMaxAgeSec. WARN: no file. NA: GFS2 is frozen, the host is in maintenance mode, the cluster\'s power-on setting is off, or corosync started under 5 minutes ago and no file has been written since.',
                      why: 'HVM failover judges hosts by these files. A stale file among fresh ones points at this host.',
                      action: 'No file is expected for up to a minute after a host leaves maintenance mode. If it stays, check its agent. MOR-03 shows whether agents are checking in at all.'],

            // ------------------------------------------------------------------ host
            'HST-01': [area: 'Host', name: 'No pending reboot',
                       what: 'WARN: /var/run/reboot-required exists. There is no row otherwise.',
                       why: 'An update on this host is waiting for a reboot to take effect.',
                       action: 'Reboot in a maintenance window, one host at a time.'],
            'HST-02': [area: 'Host', name: 'Libvirt certificates in date',
                       what: 'Full check only. Reads the end date of libvirt and qemu certificates. WARN and FAIL at the site standards certWarnDays and certFailDays, only with TLS in use on the host. NA: no certificates, or TLS not in use. NOT CHECKED: the date could not be read. Built from documentation: certificates in use have not been seen on a host.',
                       why: 'Hosts migrate over SSH by default, so a certificate nothing uses cannot break anything. With TLS in use, migrations or consoles that depend on it stop when it expires.',
                       action: 'Replace it in a maintenance window.'],
            'HST-03': [area: 'Host', name: 'Appliance certificate in date',
                       what: 'Full check only. Reads the end date from a TLS handshake with the appliance\'s own URL. WARN and FAIL at the site standards certWarnDays and certFailDays. NOT CHECKED: no certificate could be read.',
                       why: 'Agents and users reach the appliance through this certificate. It is one certificate, so every cluster reports it.',
                       action: 'Renew the appliance certificate before it ends.'],

            // ------------------------------------------------------------------ hardware
            'HW-01': [area: 'Hardware', name: 'Power supplies healthy and redundant',
                      what: 'Full check only. Reads power supply sensors with ipmitool. FAIL: a supply is failing. WARN: redundancy is not full. NOT CHECKED: no sensors read, or ipmitool is not installed, as on Morpheus-built hosts.',
                      why: 'One power supply or feed failing takes this host down, and its cluster membership with it.',
                      action: 'Check both supplies are cabled and the BMC redundancy policy is on. NOT CHECKED: install ipmitool.'],
            'HW-02': [area: 'Hardware', name: 'No memory errors',
                      what: 'Full check only. Reads the kernel\'s EDAC counters. FAIL: uncorrectable errors. WARN: correctable errors. There is no row where the host has no EDAC counters.',
                      why: 'Rising memory errors come before a host crash, and an unclean crash freezes every GFS2 datastore until it is acknowledged.',
                      action: 'Move VMs off and plan a replacement.'],
            'HW-03': [area: 'Hardware', name: 'Temperatures within limits',
                      what: 'Full check only. Reads temperature sensors with ipmitool. FAIL lists any not ok. NOT CHECKED: no sensors read, or ipmitool is not installed.',
                      why: 'A sensor outside its limits is a warning about the host\'s hardware, which a cluster member depends on.',
                      action: 'Check the host\'s cooling and the sensors listed. NOT CHECKED: install ipmitool.'],
            'HW-04': [area: 'Hardware', name: 'No serious hardware events recently',
                      what: 'Full check only. Reads the last 40 entries of the hardware event log with ipmitool, for serious events still asserted within the site standard selDays. WARN lists them. NOT CHECKED: ipmitool is not installed. An empty log with the tool present is an answer, and gives no row.',
                      why: 'A serious event can come before a host failure, and a host that fails uncleanly stalls every GFS2 datastore.',
                      action: 'Read the events listed, on the host\'s management controller. NOT CHECKED: install ipmitool.'],
            'HW-05': [area: 'Hardware', name: 'Uplinks in a bond at the same speed',
                      what: 'Full check only. Compares the speeds of the NICs within each bond. WARN: they differ. There is no row otherwise. 1G for management beside 25G for storage is a design, so bonds are not compared with each other.',
                      why: 'A failover would change the bandwidth this host has.',
                      action: 'Check the slower link\'s cable, optic and switch port, or accept it if the bond was built that way.'],
            'HW-06': [area: 'Hardware', name: 'Same firmware on identical servers',
                      what: 'Full check only. Among hosts of one product name, compares BIOS, management controller and NIC firmware. WARN lists the versions. Different models are expected to differ, so they are not compared.',
                      why: 'Identical servers on different firmware can behave differently, which makes a host problem harder to read.',
                      action: 'Bring them in line in your normal firmware work. The plugin has no fix for this.'],
            'HW-07': [area: 'Hardware', name: 'Boot disks healthy (SMART)',
                      what: 'Full check only. Reads smartctl for the disks under /. FAIL: SMART health is not good, or an NVMe critical warning. WARN: pending or uncorrectable sectors, or media errors. Reallocated sectors are only shown, as vendors encode them differently. NOT CHECKED: no smartctl, or a RAID volume or virtual disk that hides SMART. Built from documentation: a physical boot disk has not been seen.',
                      why: 'A host that loses its boot disk leaves the cluster uncleanly, which stalls every GFS2 datastore until it is acknowledged.',
                      action: 'Replace this disk in a maintenance window. No smartctl: install smartmontools. RAID or virtual: read the physical disks through their controller.'],

            // ------------------------------------------------------------------ layout
            'LAY-01': [area: 'Layout', name: 'Cluster layout recognised',
                       what: 'Reads the HVM version from the cluster\'s Morpheus layout code. PASS: 1.3 or 2.0. WARN: anything else.',
                       why: 'Standards are chosen by layout, so only checks that do not depend on the layout are meaningful.',
                       action: 'Read the results with that in mind. The plugin has no fix for this.'],
            'LAY-02': [area: 'Layout', name: 'Host OS matches the layout',
                       what: 'Compares the Ubuntu version in /etc/os-release with the site standard osVersion, which comes from the layout. FAIL: it differs.',
                       why: 'Each layout is built for one OS release.',
                       action: 'Find out how this host came to differ. The plugin has no fix for this.'],
            'LAY-04': [area: 'Layout', name: 'VirtSwitch network built with hvmcli',
                       what: 'On a VirtSwitch layout, looks for hvmcli and its netplan files. WARN: either is missing.',
                       why: 'This is how the 2.0 layout builds its network, so a host without them was not built the way the layout expects.',
                       action: 'Compare this host\'s network with another host\'s. The plugin has no fix for this.'],
            'LAY-05': [area: 'Layout', name: 'Open vSwitch management bridge present',
                       what: 'On a 1.3 layout, looks for a bridge named mgmt in Open vSwitch. WARN: not there.',
                       why: 'This is how the 1.3 layout builds its network, so a host without it was not built the way the layout expects.',
                       action: 'Compare this host\'s bridges with another host\'s. The plugin has no fix for this.'],

            // ------------------------------------------------------------------ migration
            'MIG-01': [area: 'Migration', name: 'VMs can live-migrate between every host (CPU)',
                       what: 'Compares a hash of each host\'s CPU feature flags. PASS: the same everywhere. WARN: they differ, under a named cluster CPU model. FAIL: they differ, with no named model.',
                       why: 'A VM on host-passthrough sees its host\'s CPU, so hosts that differ cannot be relied on to take each other\'s VMs.',
                       action: 'Edit the cluster and set its CPU Model, HVM\'s equivalent of EVC, to the model the finding names, which libvirt reports usable on every host. It can be set on an existing cluster, but running VMs keep their CPU until at least their next power cycle, and reports differ on whether existing VMs pick it up at all. Test on one VM first, and test a live migration in both directions.'],
            'MIG-02': [area: 'Migration', name: 'Reaches every peer on the migration port',
                       what: 'Full check only. Tries TCP 22 from each host to each corosync ring address. FAIL lists those closed.',
                       why: 'HPE documentation states TCP 22 between hosts, and hosts migrate over SSH by default.',
                       action: 'Open TCP 22 between these hosts, on the host and on whatever is between them.'],
            'MIG-03': [area: 'Migration', name: 'Same datastores active on every host',
                       what: 'Compares libvirt\'s storage pools across hosts. FAIL: a pool is missing here, or not active.',
                       why: 'Without the same datastores active, a VM has nowhere to go.',
                       action: 'Find out why this host lacks that pool. See GFS-02 if its filesystem is not mounted.'],
            'MIG-04': [area: 'Migration', name: 'Every running VM fits on another host',
                       what: 'Compares each running VM\'s memory with what other hosts, not in maintenance, have available now. WARN lists VMs that fit nowhere else.',
                       why: 'These cannot move, so their host cannot be emptied for maintenance.',
                       action: 'Free memory elsewhere before that host\'s maintenance. Can I take it down? in the Hosts section shows where each VM can go.'],
            'MIG-05': [area: 'Migration', name: 'Cluster CPU model matches the standard',
                       what: 'Runs only with the site standard clusterCpuModel set. Compares the cluster\'s CPU model with it. FAIL: it differs.',
                       why: 'You set this key to hold the cluster to one model, the equivalent of EVC.',
                       action: 'Edit the cluster\'s CPU Model, or change the key. MIG-01 says what to expect of running VMs.'],
            'MIG-06': [area: 'Migration', name: 'Running VMs use the cluster CPU model',
                       what: 'Under a named cluster CPU model, reads each qemu process for -cpu host. WARN lists VMs still on host-passthrough. NOT CHECKED: no qemu process could be read. NA: the cluster has no named model.',
                       why: 'New VMs get the cluster model. An existing VM kept host-passthrough through a stop and start in Morpheus, in the runs seen so far.',
                       action: 'Expect to rebuild the VM, and until then do not live-migrate it to a host with a different CPU.'],
            'MIG-07': [area: 'Migration', name: 'VMs can live-migrate',
                       what: 'Reads each running qemu process for CPU settings that stop migration (migratable=off, invtsc=on). WARN lists those VMs.',
                       why: 'Their CPU is pinned to this host, usually by nested virtualization, and libvirt refuses to move them. Automatic placement will keep failing on them.',
                       action: 'They must be stopped to empty this host. Plan that before its maintenance.'],

            // ------------------------------------------------------------------ Morpheus's view
            'MOR-01': [area: 'Morpheus\'s view', name: 'Morpheus host status matches the host',
                       what: 'WARN: Morpheus\'s status message for a healthy cluster member says fenced, nodedown or unclean. It stays until Morpheus clears its own message, which can outlast the event by a long time.',
                       why: 'The message is stale. Whether it affects placement has not been established.',
                       action: 'Find out whether it affects placement before relying on it.'],
            'MOR-02': [area: 'Morpheus\'s view', name: 'Morpheus member status matches the host',
                       what: 'WARN: Morpheus has a healthy cluster member as unclean, fenced or offline. On 9.1.0.1 plugins were given an empty member status, so expect it to stay silent there.',
                       why: 'Morpheus and the cluster disagree about this host.',
                       action: 'Compare with the host in Morpheus. The plugin has no fix for this.'],
            'MOR-03': [area: 'Morpheus\'s view', name: 'Morpheus agent checking in',
                       what: 'Compares the agent\'s last check-in with the site standard agentMaxAgeSec. FAIL: older than that.',
                       why: 'The agent is how Morpheus, and this plugin, reach the host. All agents dead looks the same to HB-01, and this is what shows it.',
                       action: 'Check the agent on that host.'],
            'MOR-04': [area: 'Morpheus\'s view', name: 'Morpheus has finished removing host records',
                       what: 'WARN: a host record is still being removed (deprovisioning). It is not counted as a host.',
                       why: 'A record that stays here is stuck, and holds on to its name.',
                       action: 'Normal for a few minutes after a removal. If it stays, it is stuck: look at it in Morpheus.'],
            'MOR-05': [area: 'Morpheus\'s view', name: 'Morpheus reports no problem on this host',
                       what: 'WARN: Morpheus\'s status message for a healthy cluster member has error, failed or timed out in it.',
                       why: 'The host looks healthy from here. Morpheus can leave an old message in place after the event.',
                       action: 'Check whether the message is current.'],
            'MOR-06': [area: 'Morpheus\'s view', name: 'Morpheus has no failure recorded on this cluster',
                       what: 'WARN: the cluster record\'s status is failed.',
                       why: 'Usually the last steps of adding a host failed, as its Post-Provision process will show. Those steps did not run on that host, even if it joined.',
                       action: 'Check its votes and CLU-13, and consider deleting and adding it again.'],

            // ------------------------------------------------------------------ network
            'NET-01': [area: 'Network', name: 'Bond members up',
                       what: 'Reads /proc/net/bonding. FAIL lists members that are down.',
                       why: 'The host still works but has lost its redundancy: one more failure takes the cluster network with it.',
                       action: 'Check the cable, optic and switch port.'],
            'NET-02': [area: 'Network', name: 'Corosync does not share an interface with iSCSI',
                       what: 'Compares the interface corosync\'s address is on with the interfaces routing to iSCSI portals. WARN: they are the same. This compares names, which can sit on one bond: NET-15 traces the physical ports.',
                       why: 'Storage traffic can delay corosync messages enough to get a host evicted.',
                       action: 'Separate them where you can. The plugin has no fix for this: network changes bounce the link its agent uses.'],
            'NET-03': [area: 'Network', name: 'Ring reachability',
                       what: 'Full check only. Pings each corosync ring address from each host. WARN: any loss, no answer, or a round trip over the site standard ringRttWarnMs.',
                       why: 'Cluster membership depends on these addresses answering promptly.',
                       action: 'Look at the path between the two hosts: NET-01, NET-02 and NET-10.'],
            'NET-04': [area: 'Network', name: 'Same MTU on the corosync interface of every host',
                       what: 'Compares the MTU of the interface carrying corosync. WARN: they differ. There is no row otherwise.',
                       why: 'Hosts that disagree on packet size can see each other and still lose large packets: see NET-09.',
                       action: 'Make them the same in a maintenance window. The plugin has no fix for this: changing MTU bounces the link its agent uses.'],
            'NET-05': [area: 'Network', name: 'Switch neighbour on every uplink',
                       what: 'Reads LLDP, or CDP where lldpd listens for it, per bond member that is up. WARN: nothing heard on an uplink. NA: lldpd is not running.',
                       why: 'Without it the plugin cannot see which switch each uplink lands on. It proves cabling, not VLANs: switches commonly advertise only the native VLAN.',
                       action: 'Check that the switch sends LLDP on that port. NA: run lldpd on the host if you want this and NET-06 to NET-08 answered.'],
            'NET-06': [area: 'Network', name: 'Uplinks on different switches',
                       what: 'From LLDP, compares the switches heard on a bond\'s uplinks, with two or more up. WARN: all on one switch.',
                       why: 'One switch failing or rebooting takes every uplink of this host, and its cluster membership with it.',
                       action: 'Put an uplink on a second switch.'],
            'NET-07': [area: 'Network', name: 'Same native VLAN on every uplink',
                       what: 'From LLDP, compares the native VLAN on each uplink of a bond. WARN: they differ.',
                       why: 'A failover to the other uplink would change the VLAN of untagged traffic.',
                       action: 'Correct the switch ports.'],
            'NET-08': [area: 'Network', name: 'Same native VLAN on every host',
                       what: 'From LLDP, compares native VLANs across hosts. WARN: they differ.',
                       why: 'Untagged traffic would land on a different VLAN depending on the host.',
                       action: 'Correct the switch ports, or accept it where hosts are built differently on purpose.'],
            'NET-09': [area: 'Network', name: 'Full-size packets reach every peer',
                       what: 'Full check only. Pings each corosync ring address unfragmented at the interface\'s MTU. FAIL lists those dropped.',
                       why: 'Small traffic works and large traffic vanishes: migrations hang partway with no clear error.',
                       action: 'A switch or VLAN on this path has a lower MTU than the host. Find it and correct it.'],
            'NET-10': [area: 'Network', name: 'Netmasks match their counterparts on other hosts',
                       what: 'Groups every host\'s addresses by overlapping subnet and by interface name, and compares netmasks. FAIL lists those that differ.',
                       why: 'The host with the narrower mask treats peers outside its range as off-subnet and sends them to the gateway, or nowhere: management, migration or iSCSI to those peers fails while everything else works.',
                       action: 'Correct it in the host\'s network configuration, in a maintenance window.'],
            'NET-11': [area: 'Network', name: 'VLAN carries traffic on every host',
                       what: 'Passive: whether each host\'s uplink has learned addresses on each VLAN Morpheus has for the cluster. PASS: heard on every host. NOT CHECKED: heard on some. A quiet VLAN looks the same, so this is a hint and raises no alarm. No row for a VLAN no host hears.',
                       why: 'The trunk to the silent host may not pass this VLAN, so VMs moved there would lose their network.',
                       action: 'Put the host in maintenance mode and press Test VLANs in the Hosts section, which is what settles it.'],
            'NET-12': [area: 'Network', name: 'VM ports on the VLANs Morpheus says',
                       what: 'Full check only. Reads each VM port\'s VLAN from the bridge and compares it with its Morpheus network, joined on name and MAC. WARN: it differs. FAIL: it differs, and every network on that VLAN belongs to another customer tenant. NOT CHECKED: nothing could be compared. So far only a blank-VLAN port and a tagged one have been seen, on nested hosts, not a real wrong-VLAN port.',
                       why: 'FAIL: this VM can reach another tenant\'s network. WARN: the VM is not on the network its owner thinks.',
                       action: 'FAIL: confirm on the host with its bridge\'s VLAN list and the VM\'s definition, then take the port off that VLAN, and find out how it got there. WARN: find out which is right. It clears by itself if its network was being changed just now, at the next full check.'],
            'NET-13': [area: 'Network', name: 'No unexpected trunk',
                       what: 'Full check only. Reads each VM port from the bridge. WARN: a trunk not listed in the site standard trunkAllowedVms, or a customer VM on an untagged Open vSwitch port. FAIL: the same, reaching a VLAN that belongs to another customer tenant. NOT CHECKED: an untagged port on a VM not known to be a customer\'s, or ports that could not be read.',
                       why: 'A guest on a trunk can reach other networks by tagging its traffic. Measured on 1.3: a guest on a port with no tag reached a guest on a tagged VLAN. That port is what a network with a blank VLAN or VLAN 0 builds on 1.3. That was on nested hosts, and it has not been seen on a real trunk uplink.',
                       action: 'If this VM should have a trunk, such as a firewall, add it to trunkAllowedVms. Untagged customer port: move the VM to a network with a VLAN. FAIL: confirm on the host, then take those VLANs off the port.'],
            'NET-14': [area: 'Network', name: 'Switch takes this uplink\'s frames',
                       what: 'Compares the maximum frame size the switch advertises over LLDP with the host\'s MTU. WARN: smaller. No row if the switch advertises nothing. Vendors differ on counting headers, so equal may or may not fit. Built from documentation: an advertised size has not been seen on a host.',
                       why: 'A hint, from what the switch says of itself: large frames may be dropped here.',
                       action: 'NET-09 and a VLAN test measure the real path, so go by those.'],
            'NET-15': [area: 'Network', name: 'iSCSI has physical ports of its own',
                       what: 'Traces the cluster network and iSCSI down through VLANs, bonds and bridges to physical ports. WARN: a port carries both. NOT CHECKED: the ports could not be traced.',
                       why: 'A burst of storage traffic can delay corosync on the shared ports, and losing them takes both away at once.',
                       action: 'Separate them. Where this is deliberate, as in a test environment, list NET-15 in disabledChecks in the site standards.'],
            'NET-16': [area: 'Network', name: 'Cluster network address is static',
                       what: 'Reads whether corosync\'s address on this host came from DHCP. WARN: it did.',
                       why: 'A lost or changed lease takes this host out of the cluster, because corosync.conf still lists the old address, and another machine can then be given it. Seen after a NIC rename changed the DHCP client id.',
                       action: 'Make it static or reserve it.'],

            // ------------------------------------------------------------------ packages
            'PKG-01': [area: 'Packages', name: 'Same packages and Morpheus agent on every host',
                       what: 'Compares corosync, dlm-controld, gfs2-utils, libvirt-daemon-system, qemu-system-x86 and the Morpheus agent across hosts. WARN: versions differ. NOT CHECKED: no agent version was found on a host.',
                       why: 'Hosts on different versions may not behave the same in a failure. Agent versions did not: see PKG-03.',
                       action: 'Bring them to one version in your normal patching, one host at a time. The plugin has no fix for this.'],
            'PKG-02': [area: 'Packages', name: 'Same kernel on every host',
                       what: 'Compares uname -r across hosts. WARN: they differ. There is no row otherwise.',
                       why: 'GFS2 and DLM are in the kernel, so hosts on different kernels are not running the same code.',
                       action: 'Bring them in line in your normal patching. HST-01 shows hosts waiting on a reboot.'],
            'PKG-03': [area: 'Packages', name: 'Morpheus agent is at least the version that handled a freeze correctly',
                       what: 'Compares each host\'s agent version with the site standard agentMinVersion. WARN lists those older.',
                       why: 'An older agent (3.2.6) acknowledged the wrong nodes in a real freeze, so GFS2 stayed frozen until someone acknowledged the right node by hand. Newer agents acknowledged correctly in every test. Whether that is a fix is HPE\'s to confirm.',
                       action: 'Ask HPE how to update it, and until then watch dlm_tool on the other hosts during any host removal.'],

            // ------------------------------------------------------------------ the plugin itself
            'PRB-01': [area: 'The plugin itself', name: 'Host probe completed',
                       what: 'FAIL: a host gave no complete answer to the read-only probe. Either it ran out of time, and only its DLM state is used, or nothing came back.',
                       why: 'Checks use only the hosts that finished, so findings for this host may be missing, and it counts as not answering for fixes.',
                       action: 'Ran out of time: something on this host is answering slowly, such as libvirt, the journal or multipath. No answer: the host may be down, or its agent stopped.'],
            'PRB-02': [area: 'The plugin itself', name: 'Automatic check ran',
                       what: 'An alarm only: it never appears in the tab\'s tables. Raised when an automatic check of this cluster could not run at all, with the error as its text.',
                       why: 'Nothing else would show that monitoring has stopped. What the plugin last found stays as it was, and a new freeze is not found while this lasts.',
                       action: 'Read the error in the alarm, and the appliance\'s log. It tries again at the normal interval, and the next check that runs clears the alarm: Run full check tries now.'],
            'PRB-03': [area: 'The plugin itself', name: 'Site standards are in force',
                       what: 'WARN: the Site standards plugin setting could not be read, because of a JSON error, an unknown key or a wrong type. The finding gives the error.',
                       why: 'Checks are running on the built-in standards until this is fixed, so none of your overrides or disabled checks apply.',
                       action: 'Correct it in the plugin settings.'],

            // ------------------------------------------------------------------ storage
            'STO-01': [area: 'Storage', name: 'Multipath paths healthy',
                       what: 'Reads multipath -ll per LUN, while the site standard mpio is on. FAIL: a path is not active and ready, or the map has no paths at all. WARN: only one path.',
                       why: 'A map with no paths has lost its storage, and one with a single path has no redundancy left. Lost I/O is the usual cause of a GFS2 withdrawal.',
                       action: 'FAIL: Fix offers multipath-reconfigure (iscsiadm -m session --rescan, then multipathd reconfigure), on a host in maintenance mode with no VMs. Also check the array and the storage network.'],
            'STO-02': [area: 'Storage', name: 'Map does not queue I/O forever',
                       what: 'Reads no_path_retry from multipathd, while the site standard mpio is on. WARN: "on", which queues for ever. PASS: off, or a finite retry. NOT CHECKED: dm shows queueing and multipathd gave no limit. dm\'s features line reads the same for a finite retry, so it cannot answer this alone.',
                       why: 'Queueing with no paths hangs GFS2 instead of failing the I/O.',
                       action: 'Set no_path_retry in the multipath configuration, in a maintenance window. NOT CHECKED: run multipathd show maps format "%n %Q" on the host.'],
            'STO-03': [area: 'Storage', name: 'No iSCSI session errors',
                       what: 'Counts iSCSI ping timeouts and offline-device errors in the kernel log over 24 h. WARN at the site standard iscsiErrorsWarn.',
                       why: 'These are I/O paths failing, even if multipath has recovered since.',
                       action: 'Look at STO-01 and STO-06, then the storage network on this host.'],
            'STO-04': [area: 'Storage', name: 'iSCSI multipath daemons running',
                       what: 'On a host with iSCSI sessions and multipath maps, reads systemctl for multipathd and iscsid. FAIL: either is not active.',
                       why: 'These daemons look after the paths under every GFS2 datastore on this host.',
                       action: 'Find out why it stopped. The plugin has no fix for this.'],
            'STO-05': [area: 'Storage', name: 'Same path count on every host',
                       what: 'Compares the number of paths per LUN across hosts. WARN: they differ. There is no row otherwise.',
                       why: 'A difference means the hosts do not see this LUN the same way, and one with fewer paths has less redundancy.',
                       action: 'Compare iSCSI sessions and multipath on the host that differs.'],
            'STO-06': [area: 'Storage', name: 'Storage latency',
                       what: 'Measures average I/O wait per LUN over 2 s on each host. WARN and FAIL at the site standards storageWarnMs and storageFailMs. Skipped below 20 I/Os in the sample, where one slow I/O would fail it.',
                       why: 'VM disks wait this long on every I/O.',
                       action: 'Check the other hosts. If they are slow too, look at the array; if only this one is, its paths and NICs.'],

            // ------------------------------------------------------------------ time
            'TIM-01': [area: 'Time', name: 'Clock synchronised',
                       what: 'Reads NTP and NTPSynchronized from timedatectl. FAIL: not synchronised. WARN: synchronised for now, with NTP off: the kernel keeps saying so long afterwards. NA: no answer.',
                       why: 'With NTP off nothing is correcting this clock, so it will drift. See TIM-02 for what drift does.',
                       action: 'NTP off: Fix offers ntp-enable, on a host in maintenance mode with no VMs, as starting it can step a clock under running VMs. NTP on and not synchronised: check that the time servers are reachable.'],
            'TIM-02': [area: 'Time', name: 'Host clocks agree',
                       what: 'Compares clocks through the offsets hosts measure to time servers they share, matched by address, against the site standard maxHostDriftMs. Over it: FAIL, or WARN from systemd-timesyncd\'s single samples. Hosts sharing no server get a coarse comparison in seconds against maxClockSkewSec, at most WARN. Hosts not compared are named, and that shows neither drift nor agreement.',
                       why: 'Live migration moves a running clock between hosts, and corosync and GFS2 logs stop lining up.',
                       action: 'Find the host that differs in the Time section. On systemd-timesyncd, see whether it repeats on the next check.'],
            'TIM-03': [area: 'Time', name: 'In sync with a time source',
                       what: 'Reads chrony or systemd-timesyncd against the site standard maxNtpOffsetMs. Chrony: FAIL when over it, with no source selected, or an abnormal leap status. Timesyncd: WARN when over it, as its one sample is up to half an hour old and already corrected. FAIL only if no server has answered or the leap status is abnormal. NOT CHECKED: it reported nothing to judge.',
                       why: 'Live migration and cluster timers both suffer from drift.',
                       action: 'Look at the Time section. Check this host can reach its source. On systemd-timesyncd, see whether a warning repeats on the next check.'],
            'TIM-04': [area: 'Time', name: 'Host uses the cluster time source',
                       what: 'Compares each host\'s time servers with the site standard ntpServers, which the Time section or the layout settings can set for one cluster. FAIL: not configured. WARN: configured, but following another server. NA: none defined for this cluster.',
                       why: 'A host on another source is not verified against the one you run, and hosts on different sources drift apart.',
                       action: 'FAIL: Fix offers ntp-sources, on a host in maintenance mode with no VMs: a drop-in file, marked prefer on chrony, undone on systemd-timesyncd if no listed server answers. WARN: check this host can reach the cluster source.'],
            'TIM-05': [area: 'Time', name: 'Every host configured with the same time sources',
                       what: 'Compares the configured time servers across hosts. WARN: they differ. There is no row otherwise.',
                       why: 'Hosts following different sources drift apart, even with each one "in sync".',
                       action: 'Define the cluster\'s time source in the Time section, then use TIM-04\'s fix on the hosts that differ.'],
            'TIM-06': [area: 'Time', name: 'A time source is defined for this cluster',
                       what: 'Whether the site standard ntpServers has a value, from the Time section, the site standards or the layout settings. WARN: none.',
                       why: 'With one defined every host is verified against it, and hosts on a segment that loses internet are not left drifting together unnoticed.',
                       action: 'Define it in the Time section. That changes nothing on the hosts until you run their fix.'],

            // ------------------------------------------------------------------ VMs
            'VM-01': [area: 'VMs', name: 'No VM running on two hosts',
                      what: 'Looks for one libvirt domain name running on more than one host. FAIL lists them.',
                      why: 'Two copies writing one disk corrupt it.',
                      action: 'Stop one copy immediately. Decide which by what its guest was serving.'],
            'VM-02': [area: 'VMs', name: 'No VM stuck on its disk',
                      what: 'FAIL: a qemu process on this host is in uninterruptible sleep (D state). There is no row otherwise.',
                      why: 'These VMs cannot answer on the network while they are stuck.',
                      action: 'On a frozen host, this comes from the frozen lockspace: follow DLM-01. Otherwise look at storage paths and latency (STO-01, STO-06).'],
            'VM-03': [area: 'VMs', name: 'HVM agent has VM stops queued during a freeze',
                      what: 'On a frozen host, counts the agent\'s virsh shutdown, destroy and kill commands in the journal over 15 minutes. FAIL: there are some.',
                      why: 'They take effect the moment I/O returns. In the freeze this plugin was built around, the VMs died when it ended.',
                      action: 'Expect these VMs to power off when the freeze clears, then start them.'],
            'VM-04': [area: 'VMs', name: 'Host in maintenance mode has no running VMs',
                      what: 'Counts running VMs in libvirt on a host in maintenance mode. WARN: there are some.',
                      why: 'Maintenance mode is meant to have emptied this host, and fixes and removal refuse while VMs run on it.',
                      action: 'Move or stop them before working on the host.'],
            'VM-05': [area: 'VMs', name: 'Morpheus and libvirt agree on VM power',
                      what: 'Compares Morpheus\'s power state with libvirt on the host Morpheus has the VM on. WARN: they differ. Only for hosts that answered.',
                      why: 'What Morpheus shows for this VM is not what is running.',
                      action: 'Morpheus says off and libvirt says running: do not press Start on it in Morpheus until this clears, as it is already running. Otherwise find out which is right.'],
    ]

    /** What the tab's popups and Help need: text only, from the code. */
    static Map forTab() {
        [statuses: STATUSES, notes: NOTES,
         areas: PREFIXES.collect { String prefix, String area -> [prefix: prefix, area: area] },
         checks: ENTRIES.collect { String id, Map<String, String> e -> [id: id] + e }]
    }
}
